const EVENTS = [
  {year: -776, label: "First Olympics", desc: "The ancient Olympic Games were held at Olympia in Greece for the first time, inaugurating a sacred truce among warring city-states and a tradition of athletic competition that would endure for over a millennium."},
  {year: -509, label: "Roman Republic Founded", desc: "Rome expelled its last king, Tarquinius Superbus, and established a republican government. The Senate, consuls, and assemblies it created would shape Western political thought for two thousand years."},
  {year: -330, label: "Alexander's Empire", desc: "Alexander the Great completed his conquest of the Achaemenid Persian Empire, reaching from Macedonia to the borders of India. His campaigns spread Greek language and culture across the ancient world in what we now call the Hellenistic Age."},
  {year: -221, label: "Qin Unifies China", desc: "Qin Shi Huang unified the Warring States, becoming the first Emperor of a united China. He standardized weights, measures, writing, and coinage — and began construction of the Great Wall."},
  {year: -44, label: "Caesar Assassinated", desc: "Julius Caesar was assassinated on the Ides of March by a group of senators led by Brutus and Cassius. His death plunged Rome into civil war and ultimately led to the end of the Republic and the rise of the Roman Empire."},
  {year: 79, label: "Vesuvius Erupts", desc: "Mount Vesuvius erupted catastrophically, burying the Roman cities of Pompeii and Herculaneum under meters of volcanic ash. The preserved ruins have provided an unparalleled window into daily life in the ancient Roman world."},
  {year: 476, label: "Fall of W. Rome", desc: "The Germanic chieftain Odoacer deposed Romulus Augustulus, the last Western Roman Emperor. Traditionally marking the end of Antiquity and the beginning of the Middle Ages in Europe."},
  {year: 570, label: "Birth of Muhammad", desc: "The Prophet Muhammad was born in Mecca, Arabia. His revelations, compiled as the Quran, would give rise to Islam — a faith that within a century would unite the Arabian Peninsula and reshape the political map of three continents."},
  {year: 632, label: "Islamic Expansion", desc: "Following the death of Muhammad, the Rashidun Caliphate launched a series of rapid conquests. Within a generation, Arab armies had subdued Persia, the Levant, Egypt, and North Africa in one of history's most dramatic imperial expansions."},
  {year: 800, label: "Charlemagne Crowned", desc: "Pope Leo III crowned Charlemagne Emperor of the Romans on Christmas Day in Rome. This coronation revived the idea of a Western Empire, laid the foundations of medieval Europe, and shaped the political geography of France and Germany."},
  {year: 1066, label: "Norman Conquest", desc: "William the Conqueror defeated King Harold II at the Battle of Hastings, fundamentally transforming England. The Norman Conquest reshaped English language, law, culture, and aristocracy in ways that persist to the present day."},
  {year: 1206, label: "Genghis Khan", desc: "Temüjin was proclaimed Genghis Khan — Universal Ruler — at a grand assembly of Mongol tribes. He then launched a series of conquests that would create history's largest contiguous land empire, forever altering Eurasia's political landscape."},
  {year: 1347, label: "Black Death", desc: "The bubonic plague reached Sicily from Central Asia, spreading across Europe with devastating speed. Within five years it had killed an estimated one-third of Europe's population, triggering profound social, economic, and religious upheaval."},
  {year: 1453, label: "Fall of Constantinople", desc: "Ottoman Sultan Mehmed II conquered Constantinople after a 53-day siege, ending the Byzantine Empire and the last remnant of Rome. The fall accelerated the Renaissance as Greek scholars fled west, and marked a new era of Ottoman dominance."},
  {year: 1492, label: "Columbus Voyage", desc: "Christopher Columbus, sailing for the Spanish Crown, reached the Americas. His voyage initiated sustained contact between the Old and New Worlds, leading to the Columbian Exchange and the era of European colonial empires."},
  {year: 1517, label: "Reformation", desc: "Martin Luther published his Ninety-Five Theses challenging papal authority and the sale of indulgences. His protest sparked the Protestant Reformation, permanently fracturing Western Christendom and reshaping European politics for centuries."},
  {year: 1648, label: "Peace of Westphalia", desc: "The treaties ending the Thirty Years' War established the modern concept of state sovereignty and non-interference in internal affairs. The Westphalian system remains the foundational framework of international relations."},
  {year: 1776, label: "American Independence", desc: "The thirteen American colonies declared independence from Britain, articulating Enlightenment ideals of liberty and self-governance. The United States that followed became a model for republican government worldwide."},
  {year: 1789, label: "French Revolution", desc: "The French Revolution overthrew the monarchy and swept away the old aristocratic order. Its ideals of liberté, égalité, fraternité — and the terror that followed — sent shockwaves through every royal court in Europe."},
  {year: 1815, label: "Congress of Vienna", desc: "After Napoleon's defeat, European powers met in Vienna to redraw the map of Europe. The conservative order they established maintained relative peace for nearly a century, reshaping borders and balance of power."},
  {year: 1914, label: "WWI Begins", desc: "The assassination of Archduke Franz Ferdinand triggered a chain of alliances that engulfed Europe in a catastrophic war. The Great War killed 20 million people, destroyed four empires, and set the conditions for an even deadlier conflict."},
  {year: 1945, label: "WWII Ends", desc: "World War II ended with the defeat of Nazi Germany and Imperial Japan. The war's aftermath — the United Nations, decolonization, the Cold War, and the atomic age — defined the second half of the twentieth century."},
];

